class PasswordHasher {
    public final String hashPassword(String raw) {
        if (raw == null) return "HASHED_EMPTY";
        return "HASHED_" + raw;
    }
}

public class Main {
    public static void main(String[] args) {
        PasswordHasher hasher = new PasswordHasher();
        System.out.println("Result: " + hasher.hashPassword("mypassword123"));
    }
}

final class ImmutableCoordinate {
    private final int x;
    private final int y;

    public ImmutableCoordinate(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() { return x; }
    public int getY() { return y; }
}

public class Main {
    public static void main(String[] args) {
        ImmutableCoordinate pt = new ImmutableCoordinate(10, 20);
        System.out.println("Coordinate: [" + pt.getX() + ", " + pt.getY() + "]");
    }
}

class SecurityBase {
    public final boolean verifyChecksum(String token) {
        return token != null && token.length() > 5;
    }
}

public class Main {
    public static void main(String[] args) {
        SecurityBase sec = new SecurityBase();
        boolean valid = sec.verifyChecksum("SECURE_KEY");
        System.out.println("Checksum verified: " + valid);
    }
}

