final class LicenseKeyValidator {
    private final String secretPrefix = "LIC-";

    public final boolean isValidKey(String key) {
        if (key == null) return false;
        return key.startsWith(secretPrefix) && key.length() == 12;
    }
}

public class Main {
    public static void main(String[] args) {
        LicenseKeyValidator validator = new LicenseKeyValidator();
        System.out.println("License valid: " + validator.isValidKey("LIC-99887766"));
    }
}
